export default pattern<IframeSessionCheckinInput, IframeSessionCheckinOutput>(({
  input,
  state,
}) => {
  const output = new Writable<IframeOutputData>(DEFAULT_OUTPUT);
  const context = IframeContext({
    input,
    state,
    output,
  });

  return {
    [NAME]: "Iframe · Session check-in",
    [UI]: (
      <div style={{ width: "100%", height: "720px" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
